/// Physical GPU reach-row pitch in floats; logical hand counts stay unchanged.
/// Valid poker ranges have at most 1326 hands. Keep in sync with CUDA's
/// `(nh + 7) & ~7` reach addressing, including the zero-count down sweep.
pub(crate) fn gpu_reach_pitch(nh: usize) -> usize {
    nh.div_ceil(8) * 8
}

